const groups={dl:{name:'深度学习',label:'DEEP LEARNING',desc:'建立数学直觉，用 PyTorch 写出第一个神经网络。'},cv:{name:'计算机视觉',label:'COMPUTER VISION',desc:'从像素与卷积，到目标框、IoU 和评估指标。'},yolo:{name:'YOLOv5 实战',label:'OBJECT DETECTION',desc:'读懂模型结构，完成自己的目标检测项目。'}};
const lessons=[
{id:'tensor',group:'dl',title:'张量：深度学习的基本语言',desc:'理解维度、形状与广播，建立数据的第一层直觉。',time:20,level:'入门',sections:[['从数组到张量','张量可以理解为带有形状的多维数组。标量是零维，向量是一维，矩阵是二维。一个彩色图像批次在 PyTorch 中通常写作 [N, C, H, W]：批大小、通道数、高度与宽度。先把形状写在纸上，再写网络，能省下很多排错时间。'],['形状比数值更先决定代码能否运行','矩阵乘法要求内部维度一致：[2, 3] @ [3, 4] 的结果是 [2, 4]。逐元素乘法与矩阵乘法不同。广播会从末尾对齐维度：两边相等，或其中一边为 1，才可以扩展。比如 [4, 3] 加 [3] 相当于每一行加同一个向量。'],['动手练习','创建一个 [8, 3, 224, 224] 的随机张量，计算每个通道在批次与空间上的均值。思考为什么结果保留了 3 个值。注意 permute 会改变维度顺序，而 reshape 主要改变数据的组织形状，两者不能互相替代。']],code:'import torch\n\nx = torch.randn(8, 3, 224, 224)\nchannel_mean = x.mean(dim=(0, 2, 3))\nprint(x.shape)             # torch.Size([8, 3, 224, 224])\nprint(channel_mean.shape)  # torch.Size([3])\n\na = torch.randn(2, 3)\nb = torch.randn(3, 4)\nprint((a @ b).shape)       # torch.Size([2, 4])',quiz:{q:'[2, 3] 与 [3, 4] 矩阵相乘，结果的形状是？',options:['[2, 4]','[3, 3]','[2, 3, 4]'],answer:0,why:'内部维度 3 被求和消去，外部维度 2 和 4 保留。'}},
{id:'gradient',group:'dl',title:'梯度下降与反向传播',desc:'把“学习”拆解成预测、计算误差和更新参数。',time:25,level:'入门',sections:[['模型为什么能够学习','以预测 y = wx + b 为例，模型先用当前参数产生预测，再通过损失函数衡量误差。梯度描述参数变化时损失如何变化。沿梯度的反方向走一小步，是降低损失的局部策略；并不保证每次都找到全局最优点。'],['链式法则连接整张计算图','反向传播用链式法则，从损失向前逐层计算导数。PyTorch 在前向计算时记录图结构，调用 backward 后，把可训练叶子张量的梯度累加到 grad 中。因此每次新的优化步骤前要清空梯度，避免无意累积。'],['理解学习率','更新形式为 w ← w − η∇L。η 太大可能让训练振荡，太小会让收敛缓慢。检查 loss 的变化、梯度是否有限以及数据尺度，比盲目加深网络更有价值。下面的例子学习一条合成直线，可在本地 Python 环境运行。']],code:'import torch\n\ntorch.manual_seed(0)\nx = torch.linspace(-1, 1, 100).reshape(-1, 1)\ny = 3 * x + 2\nmodel = torch.nn.Linear(1, 1)\noptimizer = torch.optim.SGD(model.parameters(), lr=0.1)\n\nfor step in range(200):\n    prediction = model(x)\n    loss = torch.nn.functional.mse_loss(prediction, y)\n    optimizer.zero_grad()\n    loss.backward()\n    optimizer.step()\nprint(model.weight.item(), model.bias.item())',quiz:{q:'每次普通训练步骤为什么调用 zero_grad()？',options:['重置模型权重','清除上一步累积的梯度','删除训练数据'],answer:1,why:'backward 默认累加梯度；清空后，本步更新只使用本步梯度。'}},
{id:'network',group:'dl',title:'搭建你的第一个神经网络',desc:'Linear、激活函数与损失函数如何共同工作。',time:30,level:'基础',sections:[['非线性让网络超越一条直线','多个线性层如果没有非线性激活，仍然等价于一个线性变换。ReLU 把负值截为零，让网络能够表达更复杂的关系。隐藏层的宽度与深度是容量选择，不是越大越好；数据量和泛化表现同样决定效果。'],['分类输出是 logits','分类网络最后一层输出每个类别的未归一化分数，称为 logits。CrossEntropyLoss 接受 logits 和整数类别标签，内部已处理相应的归一化计算，不需要提前做 softmax。标签应为 long 类型，形状通常是 [N]。'],['先用形状检查模型','下面是一个接收 28×28 灰度图、输出 10 类分数的小网络。随机数据只用于演示接口和训练步骤，不代表真实分类效果。真正训练时应接入数据集，并对独立验证集计算准确率。']],code:'import torch\nfrom torch import nn\n\nmodel = nn.Sequential(\n    nn.Flatten(),\n    nn.Linear(28 * 28, 128),\n    nn.ReLU(),\n    nn.Linear(128, 10),\n)\nimages = torch.randn(16, 1, 28, 28)\nlabels = torch.randint(0, 10, (16,))\nlogits = model(images)\nloss = nn.CrossEntropyLoss()(logits, labels)\nprint(logits.shape, loss.item())',quiz:{q:'CrossEntropyLoss 应接收什么？',options:['已经取 argmax 的类别','原始 logits 与整数标签','只接收概率最高的一项'],answer:1,why:'argmax 会丢弃连续分数，且不可用于这里的梯度优化。'}},
{id:'training',group:'dl',title:'训练循环与泛化能力',desc:'区分训练和验证，识别过拟合并保存模型。',time:30,level:'基础',sections:[['把数据分为不同角色','训练集用于优化参数，验证集用于调超参数与选模型，测试集用于最终评估。来自同一视频或同一对象的近似图像应尽量按来源分组划分，避免数据泄漏。仅看训练损失下降，无法证明模型学到了可迁移的规律。'],['train 与 eval 的职责','model.train() 与 model.eval() 会改变 Dropout、BatchNorm 等模块的行为。eval 并不会关闭梯度记录，验证时还应使用 torch.no_grad() 或 inference_mode()。保持训练与推理使用相同的预处理是另一个常见的正确性要求。'],['观察曲线再作调整','当训练误差继续下降，而验证误差升高，可能存在过拟合。可以检查数据质量、减少容量、使用增强或正则化。保存验证表现最好的权重，并记录随机种子、数据划分和参数，让实验可以比较和复现。']],code:'import torch\n\ndef train_epoch(model, loader, optimizer, loss_fn):\n    model.train()\n    for images, labels in loader:\n        loss = loss_fn(model(images), labels)\n        optimizer.zero_grad()\n        loss.backward()\n        optimizer.step()\n\ndef accuracy(model, loader):\n    model.eval()\n    correct, total = 0, 0\n    with torch.no_grad():\n        for images, labels in loader:\n            predicted = model(images).argmax(dim=1)\n            correct += (predicted == labels).sum().item()\n            total += labels.numel()\n    return correct / total if total else 0.0',quiz:{q:'model.eval() 是否自动关闭梯度记录？',options:['是','否，需要额外使用 no_grad 等上下文','仅 GPU 上会关闭'],answer:1,why:'eval 切换部分层的行为；梯度记录由另一个机制控制。'}},
{id:'image',group:'cv',title:'像素、通道与图像预处理',desc:'从 HWC 到 CHW，理解归一化与颜色空间。',time:20,level:'入门',sections:[['图像首先是数字','8 位图像的每个通道通常保存 0 到 255 的整数值。彩色图像有多个通道，读取工具可能给出不同顺序。OpenCV 默认读取 BGR，许多模型输入和显示工具采用 RGB，直接混用会导致颜色与预训练模型输入分布不一致。'],['维度与尺度要同时核对','NumPy 中的图像常用 HWC 排列；PyTorch 图像模型常用 NCHW。转换时需要重新排列轴，加入批次维，并转成浮点数。除以 255 将值缩放到 [0, 1]，进一步的均值方差标准化必须与具体模型的训练约定一致。'],['几何变换也会影响标签','目标检测的数据增强不仅改变图像，还必须同时改变边界框。直接拉伸会改变物体比例；letterbox 在等比例缩放后加边框。将预测坐标映射回原图时，需要扣除 padding，再除以缩放比例。']],code:'import cv2\nimport torch\n\nimage = cv2.imread("example.jpg")\nif image is None:\n    raise FileNotFoundError("请准备 example.jpg")\nrgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)\nrgb = cv2.resize(rgb, (224, 224))\nx = torch.from_numpy(rgb).permute(2, 0, 1)\nx = x.float().div(255).unsqueeze(0)\nprint(x.shape)  # [1, 3, 224, 224]',quiz:{q:'OpenCV 的 imread 默认通道顺序是？',options:['RGB','BGR','CHW'],answer:1,why:'BGR 是颜色通道顺序，CHW 是维度排列，二者是不同概念。'}},
{id:'cnn',group:'cv',title:'卷积神经网络与感受野',desc:'理解局部连接、权重共享和特征图。',time:30,level:'基础',sections:[['卷积核在局部寻找模式','卷积用一个小窗口扫过图像，同一组参数在空间位置共享。浅层可以对边缘和纹理产生响应，深层通过组合形成更复杂的特征。学习到的特征由训练数据和目标决定，不能把每个通道简单解释成一个固定语义。'],['算清输出尺寸','单个空间维度的输出为 floor((输入 + 2×padding − dilation×(kernel−1) − 1) / stride + 1)。当 kernel=3、padding=1、stride=1 时，空间尺寸保持不变；stride=2 通常用于下采样。通道数由卷积的 out_channels 决定。'],['感受野不是特征图大小','感受野描述一个输出位置受原输入多大范围影响。堆叠卷积与下采样可以扩大感受野，同时降低空间分辨率。检测小目标时，细粒度特征容易在下采样中丢失，这也是多尺度特征融合有价值的原因。']],code:'import torch\nfrom torch import nn\n\nblock = nn.Sequential(\n    nn.Conv2d(3, 16, kernel_size=3, padding=1),\n    nn.ReLU(),\n    nn.MaxPool2d(kernel_size=2),\n)\nx = torch.randn(4, 3, 64, 64)\ny = block(x)\nprint(y.shape)  # [4, 16, 32, 32]',quiz:{q:'3×3、padding=1、stride=1 的卷积会怎样改变空间尺寸？',options:['保持不变','减半','扩大三倍'],answer:0,why:'一圈 padding 补偿了 3×3 卷积在边缘损失的空间位置。'}},
{id:'iou',group:'cv',title:'目标检测：边界框与 IoU',desc:'量化预测框与真实框的重合程度。',time:20,level:'基础',sections:[['分类与检测的区别','分类回答图里有什么，检测还要给出每个物体的位置。一个检测结果通常包含类别、置信度和边界框。xyxy 表示左上和右下坐标，xywh 表示中心位置与宽高。计算前要保证双方坐标约定一致。'],['交并比的几何含义','IoU = 交集面积 / 并集面积。并集是两个框面积之和减去交集。完全重合时为 1，没有重合时为 0。它衡量几何一致性，不衡量类别预测是否正确，也不是置信度。'],['动手观察位置偏差','打开交互实验室，移动预测框，观察 IoU 如何随横向与纵向偏移变化。当框更小时，同样的像素偏移可能产生更大的 IoU 损失。下面的函数使用连续坐标约定，不在宽高上额外加 1。']],code:'def box_iou(a, b):\n    # a、b: [x1, y1, x2, y2]，右下角应大于左上角\n    width = max(0, min(a[2], b[2]) - max(a[0], b[0]))\n    height = max(0, min(a[3], b[3]) - max(a[1], b[1]))\n    intersection = width * height\n    area_a = max(0, a[2]-a[0]) * max(0, a[3]-a[1])\n    area_b = max(0, b[2]-b[0]) * max(0, b[3]-b[1])\n    union = area_a + area_b - intersection\n    return intersection / union if union > 0 else 0.0\n\nprint(box_iou([0, 0, 10, 10], [0, 0, 10, 10]))  # 1.0',quiz:{q:'两个有效框完全不相交时，IoU 是多少？',options:['1','0.5','0'],answer:2,why:'交集面积为零，所以交并比为零。'}},
{id:'metrics',group:'cv',title:'NMS、Precision、Recall 与 mAP',desc:'从重复框到评估指标，读懂检测结果。',time:25,level:'进阶',sections:[['去掉重复检测','NMS 先按置信度排序，保留较高分候选，再抑制与它 IoU 超过阈值的重复框，通常按类别处理。阈值过低可能误删相邻物体，过高会保留更多重复框。密集目标场景需要特别检查这种权衡。'],['误报与漏报是两种代价','Precision = TP/(TP+FP)，描述预测出的目标有多少是正确的。Recall = TP/(TP+FN)，描述真实目标有多少被找到。检测任务的 TP 还要求类别正确且满足指定 IoU 阈值；同一个真实框不能被多个预测重复计为 TP。'],['不要只比较一个 mAP 数字','AP 根据置信度排序形成的 Precision–Recall 曲线计算，mAP 再对类别取平均。mAP@0.5 和 mAP@0.5:0.95 使用不同的 IoU 条件，不能直接混为同一指标。比较模型时还要保持数据集、输入尺寸与评估协议一致。']],code:'tp, fp, fn = 80, 20, 40\nprecision = tp / (tp + fp)\nrecall = tp / (tp + fn)\nf1 = 2 * precision * recall / (precision + recall)\nprint(f"Precision: {precision:.3f}")\nprint(f"Recall:    {recall:.3f}")\nprint(f"F1:        {f1:.3f}")\n# 这里只演示统计公式，实际检测需要先匹配预测框与真实框。',quiz:{q:'提高置信度阈值，通常会产生什么权衡？',options:['召回率通常提升且误报增加','预测减少，可能降低召回率','必然提高所有指标'],answer:1,why:'过滤更多低分预测可以减少误报，但也可能丢弃正确目标；具体效果需评估。'}},
{id:'architecture',group:'yolo',title:'读懂 YOLOv5 模型结构',desc:'沿着 Backbone → Neck → Head 理解检测流程。',time:35,level:'进阶',sections:[['一张图像如何变成目标框','Backbone 提取不同尺度的特征，Neck 在尺度之间融合信息，Head 产生检测预测。你工作区的 models/yolov5s.yaml 包含 Conv、C3 和 SPPF 模块，并把三层特征交给 Detect。阅读时先跟踪每一层输入来源，再看通道与下采样倍数。'],['三尺度为什么有用','本地配置的三个检测分支对应 P3/8、P4/16 和 P5/32。输入为 640×640 时，典型特征图空间尺寸为 80×80、40×40 和 20×20。较高分辨率分支保留更多小目标信息，较低分辨率分支聚合更大范围信息。'],['区分配置与实际计算','YAML 中的层数与通道会受到 depth_multiple 和 width_multiple 缩放。配置中的 anchors 是预设框形状，不是最终预测框；网络会预测相对它们的调整。不同年代的 YOLOv5 结构存在变化，本课对应含 C3 与 SPPF 的配置。']],code:'# 在 YOLOv5 仓库根目录运行\nfrom models.yolo import Model\nimport torch\n\nmodel = Model("models/yolov5s.yaml", ch=3, nc=2)\nmodel.eval()\nwith torch.no_grad():\n    output = model(torch.zeros(1, 3, 640, 640))\nprint(type(output))\n# 对照 models/yolo.py 的 Detect.forward 查看返回结构\n# 配置阅读路径：models/yolov5s.yaml → models/yolo.py → models/common.py',quiz:{q:'Neck 的主要作用是什么？',options:['融合不同尺度特征','读入标注文件','只输出最终类别名称'],answer:0,why:'特征融合把不同分辨率与语义层次的信息组合起来。'}},
{id:'dataset',group:'yolo',title:'准备自己的检测数据集',desc:'组织目录、归一化标签并检查数据划分。',time:30,level:'实践',sections:[['先定义你要检测什么','为每个类别规定清晰的标注边界与规则。类别编号从 0 开始，同一图像可包含多个目标，每个目标一行。YOLO 检测标签采用 class x_center y_center width height，四个几何量分别除以图像宽高，转成归一化坐标。'],['图片与标签一一对应','images/train/example.jpg 对应 labels/train/example.txt；验证集采用 images/val 与 labels/val。标签值应在有效范围内且宽高为正。背景图片可以没有目标，但必须确保工具链对空标签的处理符合预期。训练前先可视化一批标签，是发现错位与漏标的直接办法。'],['建立可复现的划分','将同一视频、同一拍摄序列的图像放入同一划分，减少泄漏。下面的 data.yaml 假设数据集位于仓库根目录 datasets/myset。names 的顺序必须与标签编号一致。验证集不应直接拿训练集复制一份。']],code:'# 保存到 data/myset.yaml\npath: datasets/myset\ntrain: images/train\nval: images/val\nnames:\n  0: helmet\n  1: person\n\n# 对应标签示例：labels/train/example.txt\n# 0 0.50 0.40 0.20 0.16\n# 若图像 1000×500，框中心 (500,200)，宽200、高80，\n# 归一化后就是上面这一行。',language:'YAML',quiz:{q:'YOLO 格式的中心横坐标如何归一化？',options:['除以图像高度','除以图像宽度','除以类别数'],answer:1,why:'横坐标和宽度除以图像宽度，纵坐标和高度除以图像高度。'}},
{id:'train-yolo',group:'yolo',title:'训练与验证第一个 YOLOv5 模型',desc:'显式设置参数，读懂日志并定位训练问题。',time:45,level:'实践',sections:[['先做小规模试跑','在独立 Python 环境中安装仓库 requirements.txt，并按硬件环境选择兼容的 PyTorch。先用少量 epoch 和小 batch 确认数据加载与损失正常，再投入长时间训练。下面使用 train.py 仓库接口，需要事先准备上一课的数据文件。'],['显式参数避免默认值误导','你本地 train.py 已修改默认数据配置，因此示例明确传入 --data、--weights、--epochs、--batch-size 和 --img。Windows 多进程加载出现问题时可先设 --workers 0。显存不足时先降低 batch；CPU 也能试跑，但较慢。'],['用验证集选择权重','默认训练目录通常在 runs/train 下，重名运行会自动递增目录。检查实际打印的输出路径。best.pt 与 last.pt 含义不同：前者根据训练程序的验证 fitness 选择，后者是最后一次保存。记录验证指标与样例图，再判断模型是否改善。']],code:'# 在 YOLOv5 仓库根目录；先准备 data/myset.yaml\npython -m pip install -r requirements.txt\n\n# 首次冒烟试跑（需要本地权重，或允许自动下载）\npython train.py --data data/myset.yaml --weights yolov5s.pt --img 640 --batch-size 4 --epochs 3 --workers 0 --name myset_trial\n\n# 检查终端实际保存路径，再评估选出的权重\npython val.py --data data/myset.yaml --weights runs/train/myset_trial/weights/best.pt --img 640\n\n# 通过小规模试跑后，再提高 epochs 并按显存调整 batch。',language:'Terminal',quiz:{q:'开始长时间训练前，最有价值的操作是什么？',options:['直接把 epoch 调到最大','小规模试跑并检查标签和验证输出','删除验证集节省时间'],answer:1,why:'试跑能尽早发现路径、标注、依赖与显存问题。'}},
{id:'inference',group:'yolo',title:'推理、导出与项目复盘',desc:'使用 best.pt 检测新图像，并探索 ONNX 导出。',time:35,level:'实践',sections:[['在新图像上检验效果','detect.py 接收权重和 source，source 可以是图像、目录、视频或受支持的摄像头源。调节 --conf-thres 影响保留的检测；调节 --iou-thres 影响 NMS 抑制。先用验证集之外的新图像，观察误报、漏报和定位偏差。'],['导出不等于部署完成','ONNX 是交换模型的一种格式。导出后还需要兼容的推理运行时、一致的预处理与后处理，并检查输出数值与任务指标。量化、半精度和不同算子实现可能影响精度。测速时说明硬件、输入大小、batch 以及是否包含预处理。'],['用错误样本推动下一轮迭代','将失败样本按小目标、遮挡、光照、类别混淆等原因归类。优先修正标签与补充缺失分布，再考虑模型规模。为每次实验保存配置、数据版本与结果表，明确哪个改变带来了什么效果。']],code:'# 路径应替换为终端实际输出的训练目录\npython detect.py --weights runs/train/myset_trial/weights/best.pt --source data/images --img 640 --conf-thres 0.25 --iou-thres 0.45\n\n# 导出前按 export.py / 对应文档准备 ONNX 依赖\npython export.py --weights runs/train/myset_trial/weights/best.pt --include onnx --img 640\n\n# 复盘表建议记录：\n# 数据版本 / 参数 / mAP@0.5 / mAP@0.5:0.95 / 延迟 / 失败样本',language:'Terminal',quiz:{q:'模型成功导出 ONNX 后，下一步需要核对什么？',options:['文件存在即可结束','运行时、预处理、后处理及输出一致性','只修改文件后缀'],answer:1,why:'格式转换成功不保证完整推理流程的行为与原模型一致。'}}
];
